<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { cn } from '../../utils.js'; import { useTestResultsContext } from './context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'class'> { class?: string; children?: Snippet<[number]>; } let { class: className = '', children, ...rest }: Props = $props(); const results = useTestResultsContext('TestResultsProgress'); const passedPercent = $derived(results.summary?.total ? Math.min(100, results.summary.passed / results.summary.total * 100) : 0); const failedPercent = $derived(results.summary?.total ? Math.min(100, results.summary.failed / results.summary.total * 100) : 0);</script>
{#if results.summary}<div {...rest} class={cn('svadmin-ai-tests-part__progress', className)} data-slot="test-results-progress">{#if children}{@render children(passedPercent)}{:else}<div role="progressbar" aria-label="Tests passed" aria-valuemin="0" aria-valuemax="100" aria-valuenow={Math.round(passedPercent)}><span class="svadmin-ai-tests-part__progress-passed" style={`width:${passedPercent}%`}></span><span class="svadmin-ai-tests-part__progress-failed" style={`width:${failedPercent}%`}></span></div><p><span>{results.summary.passed}/{results.summary.total} tests passed</span><strong>{passedPercent.toFixed(0)}%</strong></p>{/if}</div>{/if}
<style>.svadmin-ai-tests-part__progress { display: grid; gap: .35rem; }.svadmin-ai-tests-part__progress > div { display: flex; height: .4rem; overflow: hidden; border-radius: 999px; background: var(--muted, transparent); }.svadmin-ai-tests-part__progress-passed { background: var(--success, currentColor); }.svadmin-ai-tests-part__progress-failed { background: var(--destructive, currentColor); }.svadmin-ai-tests-part__progress p { display: flex; justify-content: space-between; margin: 0; color: var(--muted-foreground, currentColor); font-size: .68rem; }.svadmin-ai-tests-part__progress strong { font-weight: 500; }</style>
